// V64.42 — Service Worker do portal do cliente (escopo /cliente/). Mostra a notificacao
// premium quando o navegador recebe push em background (aba fechada / tela bloqueada).
// O click abre o portal no mesmo link (openUrl injetado no payload pelo Worker server-side).
function clientSwResponse() {
  const sw = `
self.addEventListener('install', e => { self.skipWaiting(); });
self.addEventListener('activate', e => { e.waitUntil(self.clients.claim()); });
// sw-version: V64.51-mobile-touch-footer
self.addEventListener('push', function(event) {
  let data = {};
  try { data = event.data ? event.data.json() : {}; } catch (_) { data = {}; }
  const title = data.title || 'Agenda ID Seven';
  const body = data.body || '';
  const url = data.openUrl || '/';
  const options = { body: body,
    icon: data.icon || '/og/idseven-logo.png', badge: data.badge || '/og/idseven-badge.png',
    data: { url: url, eventType: data.eventType || '', taskId: data.taskId || '', phase: data.phase || '' },
    tag: data.tag || 'idseven-client', renotify: !!data.renotify };
  event.waitUntil(Promise.all([
    self.registration.showNotification(title, options),
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function(list) {
      for (const c of list) { try { c.postMessage({ type: 'idseven-push', eventType: options.data.eventType, at: Date.now() }); } catch (_) {} }
    })
  ]));
});
self.addEventListener('notificationclick', function(event) {
  event.notification.close();
  const url = (event.notification.data && event.notification.data.url) || '/';
  const ev = (event.notification.data && event.notification.data.eventType) || '';
  event.waitUntil(clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function(list) {
    for (const c of list) { try { c.postMessage({ type: 'idseven-click', url: url, eventType: ev, at: Date.now() }); } catch (_) {} }
    for (const c of list) { if (c.url.indexOf(url) !== -1 && 'focus' in c) return c.focus(); }
    if (clients.openWindow) return clients.openWindow(url);
  }));
});
`;
  return new Response(sw, {
    status: 200,
    headers: {
      "Content-Type": "application/javascript; charset=utf-8",
      "Cache-Control": "public, max-age=600",
      "Service-Worker-Allowed": "/cliente/",
    },
  });
}

