/* ───────────────────────── 3. IMAGEKIT AUTH ───────────────────────── */
async function handleImageKitAuth(request, env) {
  const privateKey = env.IMAGEKIT_PRIVATE_KEY;
  if (!privateKey) return json({ error: "IMAGEKIT_PRIVATE_KEY ausente" }, 500, env);
  const token = crypto.randomUUID();
  const expire = Math.floor(Date.now() / 1000) + 2400;
  const signature = await hmacSha1Hex(privateKey, token + expire);
  return json({ token, expire, signature }, 200, env);
}
async function hmacSha1Hex(key, msg) {
  const cryptoKey = await crypto.subtle.importKey("raw", new TextEncoder().encode(key), { name: "HMAC", hash: "SHA-1" }, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", cryptoKey, new TextEncoder().encode(msg));
  return [...new Uint8Array(sig)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

/* ───────────────────────── 4. VISÃO PÚBLICA DO CLIENTE (V64.6) ─────────────────────────
   GET /cliente/cronograma/:token  → HTML premium responsivo da Visão do Cliente.
   POST /cliente/cronograma/:token/action  → Aprovar / Pedir revisão / Editar (aditivo).

   Segurança: a única "credencial" é o shareToken (capability). Inválido → 404 HTML amigável.
   Aditivo: o POST grava clientLastAction = {type, at, note} (CAMPO NOVO), além de
   appendar a clientActions[] via array-merge — não toca cronWeeks, cs, lg, lgState, etc. */

// V64.23 — resposta dedicada a CRAWLERS de preview. HTML mínimo (só OG + corpo simples),
// sempre HTTP 200, text/html, Cache-Control de preview. Best-effort: lê o nome do cliente
// para o título; se o token não existir, ainda devolve o card premium genérico (nunca 404
// para o crawler — assim o preview nunca cai em "cru/pobre").
async function handleClientCronogramaCrawler(token, env, origin) {
  let client = "Cliente";
  try {
    const accessToken = await getAccessToken(env, FCM_SCOPE + " " + DATASTORE_SCOPE);
    const task = await queryTaskByToken(env, accessToken, token);
    if (task && task.client) client = task.client;
  } catch (_) { /* mantém card premium genérico */ }
  return new Response(crawlerCardHtml(origin, client, token), {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "public, max-age=300",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

async function handleClientCronogramaView(token, env, origin) {
  try {
    if (!token) return htmlResponse(renderClientErrorHtml("Link inválido", "O link não contém um token válido.", origin), 400);
    let accessToken;
    // Mesmo escopo usado pelo CRON p/ ler Firestore (comprovadamente funcional).
    try { accessToken = await getAccessToken(env, FCM_SCOPE + " " + DATASTORE_SCOPE); }
    catch (e) {
      console.error("[CLIENT-VIEW] auth falhou:", e && e.message);
      return htmlResponse(renderClientErrorHtml("Indisponível", "Não foi possível carregar agora. Tente novamente em instantes.", origin), 503);
    }
    const task = await queryTaskByToken(env, accessToken, token);
    if (!task) {
      console.log(`[CLIENT-VIEW] token nao encontrado: ${token.slice(0, 6)}…`);
      return htmlResponse(renderClientErrorHtml("Cronograma não encontrado",
        "Este link pode ter sido invalidado ou ainda não foi compartilhado. Fale com sua equipe ID Seven.", origin), 404);
    }
    console.log(`[CLIENT-VIEW] ok task=${task.id} client=${task.client || ""}`);
    // P2: a tela de SUCESSO só aparece na aprovação FINAL REAL.
    // V64.14 (status-consistency): o gate usa SÓ os sinais deliberados de encerramento final
    // (finalApprovalCompleted / clientFlowStatus='concluido'). O status BRUTO do kanban
    // (task.status / workflowStage = 'concluido'), que pode vir de mover o card manualmente,
    // NÃO encerra mais a Visão do Cliente — evita tela final prematura.
    if (task.finalApprovalCompleted === true || task.clientFlowStatus === "concluido") {
      return htmlResponse(renderClientSuccessHtml(task, token, origin), 200);
    }
    // V64.14: já aprovou a fase atual (temas/produção) e ainda NÃO é final? Mostra a
    // confirmação INTERMEDIÁRIA (não a página de ações aberta como se nada tivesse ocorrido).
    const acked = clientAckedPhase(task);
    if (acked) return htmlResponse(renderClientPhaseAckHtml(task, token, acked, origin), 200);
    return htmlResponse(renderClientHtml(task, token, env, origin), 200);
  } catch (e) {
    // Blindagem: qualquer erro inesperado de render/query → HTML amigável (NUNCA tela branca/JSON/corpo vazio).
    console.error("[CLIENT-VIEW] erro inesperado:", e && (e.stack || e.message));
    return htmlResponse(renderClientErrorHtml("Algo deu errado",
      "Tivemos um problema ao montar sua página. Tente novamente em instantes ou fale com a equipe ID Seven.", origin), 500);
  }
}

async function handleClientCronogramaAction(token, request, env) {
  // V64.42 — IDEMPOTENCIA: cliente que clica 2x (rede lenta, duplo toque) NAO duplica acao.
  // Usa Cloudflare Cache API (sempre disponivel, sem binding) com chave fake-URL e TTL 5 min.
  // Header opcional: X-Idempotency-Key OU Idempotency-Key (RFC draft). Tolera ausencia.
  const idemKey = request.headers.get("Idempotency-Key") || request.headers.get("X-Idempotency-Key") || "";
  const idemUrl = idemKey ? `https://idempotency.local/cliente/${token}/${encodeURIComponent(idemKey)}` : null;
  if (idemUrl) {
    try {
      const cached = await caches.default.match(new Request(idemUrl));
      if (cached) {
        const body = await cached.text();
        return new Response(body, {
          status: cached.status,
          headers: { "Content-Type": "application/json", "X-Idempotency-Replayed": "true", "Access-Control-Allow-Origin": "*" },
        });
      }
    } catch (_) { /* cache miss/erro -> processa normal */ }
  }

  let payload = {};
  try { payload = await request.json(); } catch (_) { /* tolera body vazio */ }
  const type = (payload && typeof payload.action === "string") ? payload.action.trim() : "";
  // Globais + GRANULARES por conteúdo (V64.7). Back-compat: approve/revision/edit_request.
  const ALLOWED = [
    "approve", "approveAll", "revision", "edit_request",        // globais
    "approveItem", "reviseItem", "editTheme", "editLegenda", "noteItem", "comment", // por item
  ];
  if (ALLOWED.indexOf(type) < 0) {
    return json({ ok: false, error: "ação inválida" }, 400, env);
  }
  const note = (payload && typeof payload.note === "string") ? payload.note.slice(0, 1000) : "";
  const value = (payload && typeof payload.value === "string") ? payload.value.slice(0, 4000) : "";
  let ci = null;
  if (payload && typeof payload.contentIndex === "number" && payload.contentIndex >= 0) ci = Math.floor(payload.contentIndex);
  else if (payload && typeof payload.contentIndex === "string" && /^\d+$/.test(payload.contentIndex)) ci = parseInt(payload.contentIndex, 10);

  let accessToken;
  try { accessToken = await getAccessToken(env, FCM_SCOPE + " " + DATASTORE_SCOPE); }
  catch (e) { return json({ ok: false, error: "auth falhou: " + (e && e.message) }, 200, env); }

  const task = await queryTaskByToken(env, accessToken, token);
  if (!task) return json({ ok: false, error: "token inválido" }, 404, env);

  const now = Date.now();
  const phaseIn = clientPhase(task);                                              // V64.13 — fase ANTES da escrita
  const g = await writeClientGranular(env, accessToken, task, { type, contentIndex: ci, note, value, at: now });
  // FINAL gating: só é "aprovação final" se a fase de entrada for 'final' E o eixo do cliente concluiu.
  const final = phaseIn === "final" && !!(g && (g.client === "concluido" || g.col === "concluido"));
  // V64.43 — Notification Engine: confirmação ao cliente quando ele mesmo aprova
  // (temas aprovados → produção liberada; aprovação final → cronograma concluído).
  try {
    if (g && g.client === "concluido") await notifyWorkflowEvent(env, task, "final_approved_by_client", { token });
    else if (g && g.client === "aprovado") await notifyWorkflowEvent(env, task, "themes_approved_by_client", { token });
  } catch (_) { /* best-effort */ }
  console.log(`[CLIENT-ACTION] task=${task.id} type=${type} item=${ci} phase=${phaseIn} final=${final} clientFlow=${(g && g.client) || ""} idem=${idemKey ? "yes" : "no"}`);
  const out = { ok: true, type, contentIndex: ci, at: now, final, phase: phaseIn, col: (g && g.col) || null, clientFlowStatus: (g && g.client) || null };
  const resp = json(out, 200, env);
  if (idemUrl) {
    try {
      const cacheable = new Response(JSON.stringify(out), {
        status: 200,
        headers: { "Content-Type": "application/json", "Cache-Control": "public, max-age=300" },
      });
      await caches.default.put(new Request(idemUrl), cacheable);
    } catch (_) { /* cache write falhou -> ignorar */ }
  }
  return resp;
}

/* V64.44 — autorização de EQUIPE por capability + role-lookup (sem secret no app):
   o chamador prova posse do clientReviewToken da tarefa (mesma capability do portal) e
   declara `uid`; o Worker LÊ users/{uid} via service account e autoriza SOMENTE se o
   usuário existe, está ativo e é Social/Admin (espelho do roleCat do app).
   LIMITAÇÃO HONESTA: o uid é declarado (login custom s2/SHA-256 não emite credencial
   verificável); autenticação FORTE por usuário exige Firebase Auth/emissor de sessão —
   etapa futura separada. O privilégio concedido aqui NÃO excede o que o token já permite
   no portal (approveItem do próprio cliente também limpa a pendência do item). */
const TEAM_ROLE_KW = ["social", "gestor", "gerente", "diretor", "coordena", "supervisor", "admin", "dono", "owner", "ceo", "head"];
function normRole(s) {
  return (s || "").toLowerCase()
    .replace(/[áâãà]/g, "a").replace(/[éê]/g, "e").replace(/í/g, "i")
    .replace(/[óôõ]/g, "o").replace(/ú/g, "u").replace(/ç/g, "c").trim();
}
async function lookupTeamUser(env, accessToken, uid) {
  if (!uid || !/^[A-Za-z0-9_-]{1,128}$/.test(uid)) return null;
  const url = `${FIRESTORE_BASE}/projects/${env.FCM_PROJECT_ID}/databases/(default)/documents/users/${uid}`;
  const res = await fetch(url, { headers: { "Authorization": "Bearer " + accessToken } });
  if (!res.ok) return null;
  const doc = await res.json();
  const f = (doc && doc.fields) || {};
  const status = (f.status && f.status.stringValue) || "";
  if (status === "pendente" || status === "removido" || status === "excluido") return null;
  const admin = !!(f.admin && f.admin.booleanValue);
  const role = normRole(f.role && f.role.stringValue);
  if (!admin && !TEAM_ROLE_KW.some((k) => role.indexOf(k) >= 0)) return null;
  // salt/pass: usados SOMENTE pela rota /team/session p/ prova de senha; nunca logados.
  return { uid, name: (f.name && f.name.stringValue) || "", role: role, admin,
           salt: (f.salt && f.salt.stringValue) || "", pass: (f.pass && f.pass.stringValue) || "" };
}

/* ═══════════════ V64.45 — TEAM SESSION JWT (autenticação FORTE da equipe) ═══════════════
   PROVA DE IDENTIDADE: a senha REAL do usuário (única credencial que NÃO está legível no
   Firestore — o hash `pass` é client-readable, então hash-como-prova seria forjável).
   POST /team/session {uid, password} → Worker verifica s2:SHA-256(salt|senha) server-side
   contra users/{uid}.pass + role Social/Admin ATIVO → emite JWT HS256 assinado com
   env.TEAM_SESSION_SECRET (server-side; NUNCA no app):
     { sub: uid, name, aud: "idseven-team", scope: "workflow:team_adjusted_item",
       iat, exp: +12h }
   A team-action exige Authorization: Bearer <jwt> (assinatura+exp+aud+scope) E reconsulta
   role/status no Firestore antes de executar (revogação imediata ao desativar o usuário).
   Sem env.TEAM_SESSION_SECRET → 503 (gated por secret, como VAPID). */
const TEAM_JWT_AUD = "idseven-team";
const TEAM_JWT_SCOPE = "workflow:team_adjusted_item";
async function teamHmacKey(env) {
  return crypto.subtle.importKey("raw", new TextEncoder().encode(env.TEAM_SESSION_SECRET),
    { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
}
async function signTeamJwt(env, claims) {
  const enc = new TextEncoder();
  const h = bytesToB64u(enc.encode(JSON.stringify({ typ: "JWT", alg: "HS256" })));
  const c = bytesToB64u(enc.encode(JSON.stringify(claims)));
  const key = await teamHmacKey(env);
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", key, enc.encode(h + "." + c)));
  return h + "." + c + "." + bytesToB64u(sig);
}
async function verifyTeamJwt(env, jwt) {
  if (!env.TEAM_SESSION_SECRET) return { ok: false, error: "TEAM_SESSION_NOT_CONFIGURED" };
  const parts = (jwt || "").split(".");
  if (parts.length !== 3) return { ok: false, error: "jwt malformado" };
  const enc = new TextEncoder();
  let okSig = false;
  try {
    const key = await teamHmacKey(env);
    okSig = await crypto.subtle.verify("HMAC", key, b64uToBytes(parts[2]), enc.encode(parts[0] + "." + parts[1]));
  } catch (_) { okSig = false; }
  if (!okSig) return { ok: false, error: "assinatura inválida" };
  let claims;
  try { claims = JSON.parse(new TextDecoder().decode(b64uToBytes(parts[1]))); }
  catch (_) { return { ok: false, error: "claims inválidas" }; }
  const now = Math.floor(Date.now() / 1000);
  if (!claims.exp || claims.exp < now) return { ok: false, error: "token expirado", expired: true };
  if (claims.aud !== TEAM_JWT_AUD) return { ok: false, error: "aud inválida" };
  if (String(claims.scope || "").split(" ").indexOf(TEAM_JWT_SCOPE) < 0) return { ok: false, error: "scope insuficiente" };
  if (!claims.sub) return { ok: false, error: "sub ausente" };
  return { ok: true, uid: claims.sub, name: claims.name || "" };
}
// Paridade com o login do app (verifyPw): s2:SHA-256(salt|senha) atual + djb2 legado.
function djb2Hash(s) { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return "h" + (h >>> 0); }
async function sha256HexW(s) {
  const b = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return Array.from(new Uint8Array(b)).map((x) => x.toString(16).padStart(2, "0")).join("");
}

/* ═══════ V64.46 — HARDENING da autenticação de equipe ═══════
   - timingSafeEqualStr: comparação em TEMPO CONSTANTE (digere ambos os lados com
     SHA-256 e compara por XOR acumulado — independe do tamanho, sem early-exit).
   - rate limit por uid E por IP (CF-Connecting-IP): 5 tentativas inválidas/5min →
     bloqueio de 15min (backoff). Estado em Cache API (sem KV). LIMITAÇÃO HONESTA:
     Cache API é por datacenter e não-atômica — é mitigação best-effort; rate limit
     global exigiria KV/Durable Object (binding novo = mudança de deploy futura).
   - erros EXTERNOS genéricos ("credenciais inválidas") — não revela se uid existe,
     se a role está errada ou se a senha está errada; detalhe só em log interno.
   - logs com uid MASCARADO; nunca senha/hash/JWT/secret.
   - TTL do JWT: 4h (reduzido de 12h). */
const TEAM_JWT_TTL_S = 4 * 3600;
const TEAM_RL_MAX = 5;          // tentativas inválidas por janela
const TEAM_RL_WINDOW_S = 300;   // janela de contagem (5 min)
const TEAM_RL_BLOCK_S = 900;    // bloqueio/backoff (15 min)
function maskUid(v) { const s = String(v || ""); return s ? (s.slice(0, 3) + "…") : "(vazio)"; }
function rlDecide(state, nowS) {
  if (state && state.until && nowS < state.until) return { blocked: true, retryAfter: state.until - nowS };
  return { blocked: false };
}
function rlOnFail(state, nowS) {
  const inWindow = state && typeof state.first === "number" && (nowS - state.first) < TEAM_RL_WINDOW_S;
  const s = inWindow ? { fails: (state.fails || 0) + 1, first: state.first } : { fails: 1, first: nowS };
  if (s.fails >= TEAM_RL_MAX) s.until = nowS + TEAM_RL_BLOCK_S;
  return s;
}
async function rlGet(key) {
  try { const r = await caches.default.match(new Request("https://ratelimit.local/" + key)); return r ? await r.json() : null; }
  catch (_) { return null; }
}
async function rlPut(key, state, ttlS) {
  try { await caches.default.put(new Request("https://ratelimit.local/" + key), new Response(JSON.stringify(state), { headers: { "Cache-Control": "public, max-age=" + ttlS } })); }
  catch (_) { /* best-effort */ }
}
async function rlClear(key) {
  try { await caches.default.delete(new Request("https://ratelimit.local/" + key)); } catch (_) { /* best-effort */ }
}
async function timingSafeEqualStr(a, b) {
  const enc = new TextEncoder();
  const da = new Uint8Array(await crypto.subtle.digest("SHA-256", enc.encode("tse|" + String(a))));
  const db_ = new Uint8Array(await crypto.subtle.digest("SHA-256", enc.encode("tse|" + String(b))));
  let diff = 0;
  for (let i = 0; i < da.length; i++) diff |= da[i] ^ db_[i];
  return diff === 0;
}

/* CORS/ORIGEM (auditoria documentada): o Desktop é Electron — o renderer envia Origin
   "null"/file, então restrição por Origin NÃO se aplica a ele (e o navegador é quem
   aplica CORS, não o servidor). corsHeaders(env) continua emitindo ALLOWED_ORIGIN p/
   contextos web. A PROTEÇÃO REAL destas rotas é a autenticação (senha server-side +
   JWT + rate limit), não o CORS. */
async function handleTeamSession(request, env) {
  if (!env.TEAM_SESSION_SECRET) return json({ ok: false, error: "TEAM_SESSION_NOT_CONFIGURED" }, 503, env);
  let p;
  try { p = await request.json(); } catch (_) { return json({ ok: false, error: "credenciais inválidas" }, 401, env); }
  const uid = (p && typeof p.uid === "string") ? p.uid.trim() : "";
  const password = (p && typeof p.password === "string") ? p.password : "";
  if (!uid || !password) return json({ ok: false, error: "credenciais inválidas" }, 401, env);
  const nowS = Math.floor(Date.now() / 1000);
  const ip = request.headers.get("CF-Connecting-IP") || "0.0.0.0";
  const kUid = "team-session/uid/" + uid;
  const kIp = "team-session/ip/" + ip;
  const stUid = await rlGet(kUid);
  const stIp = await rlGet(kIp);
  if (rlDecide(stUid, nowS).blocked || rlDecide(stIp, nowS).blocked) {
    console.warn(`[TEAM-SESSION] rate-limited uid=${maskUid(uid)} ip=${maskUid(ip)}`);
    return json({ ok: false, error: "muitas tentativas — aguarde alguns minutos" }, 429, env);
  }
  let accessToken;
  try { accessToken = await getAccessToken(env, DATASTORE_SCOPE); }
  catch (e) { return json({ ok: false, error: "indisponível no momento" }, 502, env); }
  const u = await lookupTeamUser(env, accessToken, uid);
  // prova de identidade: senha verificada SERVER-SIDE em tempo constante (nunca logada).
  let okPw = false;
  if (u && u.pass && u.pass.startsWith("s2:") && u.salt) {
    okPw = await timingSafeEqualStr(u.pass, "s2:" + await sha256HexW(u.salt + "|" + password));
  } else if (u && u.pass) {
    okPw = await timingSafeEqualStr(u.pass, djb2Hash(password));
  } else {
    // uid inexistente/sem role: compare DUMMY p/ aproximar o tempo do caminho real
    // (não revela por timing se o usuário existe).
    await timingSafeEqualStr("s2:" + await sha256HexW("dummy|" + password), "s2:nunca-bate");
  }
  if (!u || !okPw) {
    const fU = rlOnFail(stUid, nowS);
    const fI = rlOnFail(stIp, nowS);
    await rlPut(kUid, fU, TEAM_RL_BLOCK_S + TEAM_RL_WINDOW_S);
    await rlPut(kIp, fI, TEAM_RL_BLOCK_S + TEAM_RL_WINDOW_S);
    // log interno com uid mascarado + código do motivo; resposta EXTERNA genérica.
    console.warn(`[TEAM-SESSION] negado uid=${maskUid(uid)} code=${!u ? "USER" : "PW"} fails=${fU.fails}${fU.until ? " (bloqueado)" : ""}`);
    return json({ ok: false, error: "credenciais inválidas" }, 401, env);
  }
  await rlClear(kUid);
  await rlClear(kIp);
  const jwt = await signTeamJwt(env, { sub: uid, name: u.name || "", aud: TEAM_JWT_AUD, scope: TEAM_JWT_SCOPE, iat: nowS, exp: nowS + TEAM_JWT_TTL_S });
  console.log(`[TEAM-SESSION] emitido uid=${maskUid(uid)} ttl=${TEAM_JWT_TTL_S}s`);
  return json({ ok: true, token: jwt, expiresIn: TEAM_JWT_TTL_S }, 200, env);
}

/* V64.45 — TEAM ACTION (camada CENTRAL de workflow): limpa clientItems[iX].cs (preserva
   phase), registra history e chama notifyWorkflowEvent() — Web Push real quando configurado,
   fallback whatsapp_premium sinalizado, dedup no engine, push NUNCA bloqueia a ação.
   AUTENTICAÇÃO FORTE (uma das duas):
     a) X-Team-Key === env.TEAM_API_KEY (server-to-server; NUNCA embutida em app cliente);
     b) Authorization: Bearer <teamSessionJwt> emitido por /team/session (assinatura HS256
        + exp + aud + scope verificados) E reconsulta de role/status no Firestore ANTES de
        executar. O clientReviewToken da URL apenas IDENTIFICA a tarefa — NÃO autoriza.
        uid declarado no body NÃO é aceito como prova de identidade.
   Idempotência: header Idempotency-Key (Cache API, TTL 300s) — verificada APÓS a
   autorização (replay nunca vaza resposta a chamador não autenticado).
   Body: { contentIndex | contentIndexes[], byName?, action?: 'adjustedItem' } */
async function handleClientCronogramaTeamAction(token, request, env) {
  let payload = {};
  try { payload = await request.json(); } catch (_) { /* tolera body vazio */ }
  const action = (payload && typeof payload.action === "string" && payload.action.trim()) || "adjustedItem";
  // V64.48 — 'contentSent': a equipe acabou de ENVIAR o cronograma ao cliente (WhatsApp
  // Business manual). Dispara o Notification Engine (themes_sent_to_client ou
  // final_content_sent_to_client conforme a fase) SEM escrever no Firestore — o Desktop já
  // gravou o envio. Com subscription → Web Push imediato; sem → fallback whatsapp_premium
  // sinalizado e logado. Mesma autenticação forte de adjustedItem.
  if (action !== "adjustedItem" && action !== "contentSent") {
    return json({ ok: false, error: "acao inválida (apenas adjustedItem ou contentSent)" }, 400, env);
  }
  // contentIndexes[] (vários itens) ou contentIndex (um) — exigido só em adjustedItem.
  const idxs = [];
  const pushIdx = (v) => {
    if (typeof v === "number" && v >= 0) idxs.push(Math.floor(v));
    else if (typeof v === "string" && /^\d+$/.test(v)) idxs.push(parseInt(v, 10));
  };
  if (Array.isArray(payload && payload.contentIndexes)) payload.contentIndexes.forEach(pushIdx);
  else if (payload && payload.contentIndex != null) pushIdx(payload.contentIndex);
  const uniq = Array.from(new Set(idxs)).sort((a, b) => a - b).slice(0, 50);
  if (action === "adjustedItem" && !uniq.length) return json({ ok: false, error: "contentIndex(es) obrigatorio" }, 400, env);

  let accessToken;
  try { accessToken = await getAccessToken(env, FCM_SCOPE + " " + DATASTORE_SCOPE); }
  catch (e) { return json({ ok: false, error: "auth falhou: " + (e && e.message) }, 200, env); }

  // ── AUTENTICAÇÃO FORTE (antes de QUALQUER efeito, inclusive replay de idempotência) ──
  let byName = (payload && typeof payload.byName === "string") ? payload.byName.slice(0, 80) : "";
  const suppliedKey = request.headers.get("X-Team-Key") || "";
  // comparação em tempo constante (hardening V64.46) — só server-to-server.
  const keyOk = !!(env.TEAM_API_KEY && await timingSafeEqualStr(suppliedKey, env.TEAM_API_KEY));
  if (!keyOk) {
    const authz = request.headers.get("Authorization") || "";
    const m = authz.match(/^Bearer\s+(.+)$/i);
    if (!m) {
      console.warn("[TEAM-ACTION] negado: sem Bearer/X-Team-Key");
      return json({ ok: false, error: "unauthorized: Authorization Bearer <teamSessionJwt> obrigatório (obtido em /team/session) ou X-Team-Key server-to-server" }, 401, env);
    }
    const v = await verifyTeamJwt(env, m[1]);
    if (!v.ok) {
      console.warn("[TEAM-ACTION] negado: jwt " + v.error);
      return json({ ok: false, error: "unauthorized: " + v.error, expired: !!v.expired }, 401, env);
    }
    // reconsulta role/status no Firestore ANTES de executar (revogação imediata).
    const teamUser = await lookupTeamUser(env, accessToken, v.uid);
    if (!teamUser) {
      console.warn(`[TEAM-ACTION] negado: uid=${maskUid(v.uid)} não é mais Social/Admin ativo`);
      return json({ ok: false, error: "forbidden: usuário não é mais Social/Admin ativo" }, 403, env);
    }
    if (!byName) byName = teamUser.name || v.name || "Equipe";
    console.log(`[TEAM-ACTION] autorizado por teamSessionJwt uid=${maskUid(teamUser.uid)} role=${teamUser.role}${teamUser.admin ? "(admin)" : ""}`);
  }
  if (!byName) byName = "Equipe";

  // Idempotência (replay devolve a resposta original, sem reaplicar) — APÓS a autorização.
  const idemKey = request.headers.get("Idempotency-Key") || request.headers.get("X-Idempotency-Key") || "";
  const idemUrl = idemKey ? `https://idempotency.local/team/${token}/${encodeURIComponent(idemKey)}` : null;
  if (idemUrl) {
    try {
      const cached = await caches.default.match(new Request(idemUrl));
      if (cached) {
        const body = await cached.text();
        return new Response(body, { status: cached.status, headers: { "Content-Type": "application/json", "X-Idempotency-Replayed": "true", "Access-Control-Allow-Origin": "*" } });
      }
    } catch (_) { /* segue sem replay */ }
  }

  const task = await queryTaskByToken(env, accessToken, token);
  if (!task) return json({ ok: false, error: "token inválido" }, 404, env);

  // V64.48 — contentSent: SÓ notifica (nenhuma escrita no banco; o envio já foi gravado
  // pelo Desktop). O resultado do engine (channel/sent/fallback/reason) volta ao chamador
  // e fica no log — prova real de push × fallback WhatsApp.
  if (action === "contentSent") {
    let pushSent = { sent: 0 };
    try {
      const evSent = clientPhase(task) === "final" ? "final_content_sent_to_client" : "themes_sent_to_client";
      pushSent = await notifyWorkflowEvent(env, task, evSent, { token });
    } catch (e) { pushSent = { sent: 0, error: e && e.message }; }
    console.log(`[TEAM-ACTION] contentSent task=${task.id} by=${byName} push=${JSON.stringify(pushSent)}`);
    const outSent = { ok: true, taskId: task.id, action: "contentSent", push: pushSent };
    if (idemUrl) {
      try {
        await caches.default.put(new Request(idemUrl), new Response(JSON.stringify(outSent), {
          status: 200, headers: { "Content-Type": "application/json", "Cache-Control": "public, max-age=300" },
        }));
      } catch (_) { /* sem persistir replay */ }
    }
    return json(outSent, 200, env);
  }

  const now = Date.now();
  const taskId = task.id;
  // updateMask cirurgico POR item: zera cs (preserva phase) + autor/timestamp.
  const itemsField = {};
  const mask = ["updatedAt"];
  uniq.forEach((ci) => {
    const key = "i" + ci;
    itemsField[key] = { mapValue: { fields: {
      cs: { nullValue: null },
      teamAdjustedAt: { integerValue: String(now) },
      teamAdjustedBy: { stringValue: byName },
    } } };
    mask.push("clientItems." + key + ".cs", "clientItems." + key + ".teamAdjustedAt", "clientItems." + key + ".teamAdjustedBy");
  });
  const fields = {
    clientItems: { mapValue: { fields: itemsField } },
    updatedAt: { integerValue: String(now) },
  };
  const lbl = uniq.length > 1
    ? "Equipe corrigiu os conteúdos " + uniq.map((i) => i + 1).join(", ")
    : "Equipe corrigiu o conteúdo " + (uniq[0] + 1);
  const histFields = {
    type: { stringValue: "equipe_corrigiu_item" },
    label: { stringValue: lbl },
    at: { integerValue: String(now) },
    by: { stringValue: byName },
    channel: { stringValue: "team_internal" },
    contentIndex: { integerValue: String(uniq[0]) },
  };
  const docName = `projects/${env.FCM_PROJECT_ID}/databases/(default)/documents/tasks/${taskId}`;
  const body = {
    writes: [{
      update: { name: docName, fields },
      updateMask: { fieldPaths: mask },
      updateTransforms: [{ fieldPath: "history", appendMissingElements: { values: [{ mapValue: { fields: histFields } }] } }],
    }],
  };
  const url = `${FIRESTORE_BASE}/projects/${env.FCM_PROJECT_ID}/databases/(default)/documents:commit`;
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Authorization": "Bearer " + accessToken, "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      const t = (await res.text()).slice(0, 240);
      console.warn("[TEAM-ACTION] commit falhou:", res.status, t);
      return json({ ok: false, error: "commit falhou: " + t }, 500, env);
    }
  } catch (e) {
    console.warn("[TEAM-ACTION] erro:", e && e.message);
    return json({ ok: false, error: "erro: " + (e && e.message) }, 500, env);
  }
  // Notification Engine (CAMADA CENTRAL): theme_adjusted_by_team / final_adjusted_by_team.
  // Web Push real ao cliente quando há subscription+VAPID; senão fallback whatsapp_premium
  // sinalizado. try/catch: falha de push NUNCA desfaz/bloqueia a ação de negócio.
  let pushResult = { sent: 0 };
  try {
    const evType = clientPhase(task) === "final" ? "final_adjusted_by_team" : "theme_adjusted_by_team";
    pushResult = await notifyWorkflowEvent(env, task, evType, { contentIndex: uniq[0], token });
  } catch (e) { pushResult = { sent: 0, error: e && e.message }; }
  console.log(`[TEAM-ACTION] task=${taskId} itens=${uniq.join(",")} by=${byName} push=${JSON.stringify(pushResult)}`);
  const out = { ok: true, taskId, contentIndexes: uniq, at: now, push: pushResult };
  const resp = json(out, 200, env);
  if (idemUrl) {
    try {
      await caches.default.put(new Request(idemUrl), new Response(JSON.stringify(out), {
        status: 200, headers: { "Content-Type": "application/json", "Cache-Control": "public, max-age=300" },
      }));
    } catch (_) { /* sem persistir replay */ }
  }
  return resp;
}

/* V64.42 — PWA Web Push: opt-in do cliente. O portal usa o Push API do navegador
   (navigator.serviceWorker + pushManager.subscribe) e POSTa a PushSubscription aqui;
   gravamos em tasks/{id}.clientPushSubs[] (array de subscriptions {endpoint, keys.p256dh, keys.auth}).
   O envio (broadcastWebPush) so funciona com env.VAPID_PRIVATE_KEY/env.VAPID_PUBLIC_KEY/env.VAPID_SUBJECT
   configurados — sem isso, broadcastWebPush retorna 'NOT_CONFIGURED'. */
/* V64.50 — endpoint mascarado p/ logs/respostas (origem + últimos 8 chars; nunca o token FCM inteiro). */
function maskEndpoint(e) {
  try { const u = new URL(e); return u.origin + "/…" + e.slice(-8); } catch (_) { return "(endpoint inválido)"; }
}
/* V64.50 — PUSH DE TESTE: dispara um push real para as subscriptions DESTE cronograma.
   NÃO altera nenhum estado da tarefa. Devolve o resultado VERDADEIRO por endpoint
   (status do POST ao push service, gone, erro) — prova fim-a-fim pós-ativação. */
async function handleClientPushTest(token, request, env) {
  // rate-limit: 1 teste por token a cada 30s (Cache API, best-effort)
  const rlUrl = "https://push-test-rl.local/" + encodeURIComponent(token);
  try {
    const hit = await caches.default.match(new Request(rlUrl));
    if (hit) return json({ ok: false, error: "aguarde 30s entre testes" }, 429, env);
  } catch (_) {}
  let accessToken;
  try { accessToken = await getAccessToken(env, FCM_SCOPE + " " + DATASTORE_SCOPE); }
  catch (e) { return json({ ok: false, error: "auth: " + (e && e.message) }, 200, env); }
  const task = await queryTaskByToken(env, accessToken, token);
  if (!task) return json({ ok: false, error: "token inválido" }, 404, env);
  const subs = Array.isArray(task.clientPushSubs) ? task.clientPushSubs : [];
  if (!subs.length) {
    console.log(`[PUSH-TEST] task=${task.id} subsFound=0 → sem_subscription`);
    return json({ ok: true, sent: 0, total: 0, reason: "sem_subscription" }, 200, env);
  }
  const out = await broadcastWebPush(env, subs,
    { title: "Teste de avisos — Agenda ID Seven", body: "Os avisos deste cronograma estão funcionando. 💜",
      openUrl: "/cliente/cronograma/" + token, tag: "idseven-push-test",
      icon: "/og/idseven-logo.png", badge: "/og/idseven-badge.png",
      eventType: "push_test", taskId: task.id, phase: "test" },
    { topic: "push_test", urgency: "high", ttl: 600 });
  if (out.gone && out.gone.length) { try { await pruneClientPushSubs(env, task, out.gone); } catch (_) {} }
  const results = (out.results || []).map((r, i) => ({
    endpoint: maskEndpoint(subs[i] && subs[i].endpoint), ok: !!r.ok,
    status: r.status || 0, gone: !!r.gone, error: r.error || null,
  }));
  console.log(`[PUSH-TEST] task=${task.id} subsFound=${subs.length} sent=${out.sent} results=${JSON.stringify(results)}`);
  try {
    await caches.default.put(new Request(rlUrl), new Response("1", { status: 200, headers: { "Cache-Control": "public, max-age=30" } }));
  } catch (_) {}
  return json({ ok: true, sent: out.sent, total: out.total, pruned: (out.gone || []).length, results }, 200, env);
}

async function handleClientPushSubscribe(token, request, env) {
  let payload;
  try { payload = await request.json(); } catch (_) { return json({ ok: false, error: "JSON invalido" }, 400, env); }
  if (!payload || typeof payload.endpoint !== "string" || !payload.endpoint || !payload.keys) {
    return json({ ok: false, error: "subscription invalida (endpoint+keys obrigatorios)" }, 400, env);
  }
  let accessToken;
  try { accessToken = await getAccessToken(env, FCM_SCOPE + " " + DATASTORE_SCOPE); }
  catch (e) { return json({ ok: false, error: "auth: " + (e && e.message) }, 200, env); }

  const task = await queryTaskByToken(env, accessToken, token);
  if (!task) return json({ ok: false, error: "token inválido" }, 404, env);

  const now = Date.now();
  const subEntry = {
    endpoint: { stringValue: payload.endpoint.slice(0, 2000) },
    keys: { mapValue: { fields: {
      p256dh: { stringValue: String(payload.keys.p256dh || "").slice(0, 200) },
      auth: { stringValue: String(payload.keys.auth || "").slice(0, 200) },
    } } },
    at: { integerValue: String(now) },
    ua: { stringValue: (request.headers.get("user-agent") || "").slice(0, 200) },
  };
  // arrayUnion via appendMissingElements em clientPushSubs (array de maps)
  const docName = `projects/${env.FCM_PROJECT_ID}/databases/(default)/documents/tasks/${task.id}`;
  const body = {
    writes: [{
      update: { name: docName, fields: { updatedAt: { integerValue: String(now) } } },
      updateMask: { fieldPaths: ["updatedAt"] },
      updateTransforms: [{ fieldPath: "clientPushSubs", appendMissingElements: { values: [{ mapValue: { fields: subEntry } }] } }],
    }],
  };
  const url = `${FIRESTORE_BASE}/projects/${env.FCM_PROJECT_ID}/databases/(default)/documents:commit`;
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Authorization": "Bearer " + accessToken, "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      const t = (await res.text()).slice(0, 240);
      return json({ ok: false, error: "commit falhou: " + t }, 500, env);
    }
  } catch (e) {
    return json({ ok: false, error: "erro: " + (e && e.message) }, 500, env);
  }
  console.log(`[PUSH-SUB] task=${task.id} endpoint=${payload.endpoint.slice(0, 60)}...`);
  return json({ ok: true, taskId: task.id, at: now, vapidConfigured: !!(env.VAPID_PRIVATE_KEY && env.VAPID_PUBLIC_KEY) }, 200, env);
}

/* ═══════════════ V64.43 — WEB PUSH REAL (RFC 8030 + 8291 + 8292) ═══════════════
   Implementação 100% Web Crypto (suportada nativamente pelo runtime de Workers):
   - ECDH P-256 (deriveBits)  → segredo compartilhado com a chave p256dh do navegador
   - HKDF-SHA256 (deriveBits) → IKM/CEK/NONCE conforme RFC 8291 (aes128gcm)
   - AES-128-GCM (encrypt)    → cifra o payload (registro único, delimitador 0x02)
   - ECDSA P-256 (sign)       → VAPID JWT ES256 (RFC 8292)
   Sem dependências externas. Sem mock: o envio é um POST real ao push service
   (fcm.googleapis.com / mozilla / windows.com etc.) do endpoint da subscription. */

function b64uToBytes(s) {
  const pad = "=".repeat((4 - (s.length % 4)) % 4);
  const b = (s + pad).replace(/-/g, "+").replace(/_/g, "/");
  const raw = atob(b);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}
function bytesToB64u(bytes) {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function concatBytes() {
  let total = 0;
  for (let i = 0; i < arguments.length; i++) total += arguments[i].length;
  const out = new Uint8Array(total);
  let off = 0;
  for (let i = 0; i < arguments.length; i++) { out.set(arguments[i], off); off += arguments[i].length; }
  return out;
}
async function hkdfBits(saltBytes, ikmBytes, infoBytes, len) {
  const key = await crypto.subtle.importKey("raw", ikmBytes, "HKDF", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "HKDF", hash: "SHA-256", salt: saltBytes, info: infoBytes }, key, len * 8);
  return new Uint8Array(bits);
}

/* RFC 8291 — cifra `payloadStr` para a subscription do navegador (p256dh + auth).
   Retorna o corpo binário completo no formato aes128gcm:
   salt(16) || rs(4) || idlen(1) || as_public(65) || ciphertext(payload+0x02+tag). */
async function encryptWebPushPayload(payloadStr, p256dhB64u, authB64u) {
  const uaPublic = b64uToBytes(p256dhB64u);            // ponto P-256 não comprimido (65 bytes)
  const authSecret = b64uToBytes(authB64u);            // 16 bytes
  if (uaPublic.length !== 65) throw new Error("p256dh inválida (esperado 65 bytes, veio " + uaPublic.length + ")");
  if (authSecret.length !== 16) throw new Error("auth inválida (esperado 16 bytes, veio " + authSecret.length + ")");
  const asKeys = await crypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, true, ["deriveBits"]);
  const asPublic = new Uint8Array(await crypto.subtle.exportKey("raw", asKeys.publicKey)); // 65 bytes
  const uaKey = await crypto.subtle.importKey("raw", uaPublic, { name: "ECDH", namedCurve: "P-256" }, false, []);
  const ecdhSecret = new Uint8Array(await crypto.subtle.deriveBits({ name: "ECDH", public: uaKey }, asKeys.privateKey, 256));
  const enc = new TextEncoder();
  // IKM = HKDF(salt=auth_secret, IKM=ecdh_secret, info="WebPush: info"||0x00||ua_public||as_public, 32)
  const keyInfo = concatBytes(enc.encode("WebPush: info\u0000"), uaPublic, asPublic);
  const ikm = await hkdfBits(authSecret, ecdhSecret, keyInfo, 32);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const cek = await hkdfBits(salt, ikm, enc.encode("Content-Encoding: aes128gcm\u0000"), 16);
  const nonce = await hkdfBits(salt, ikm, enc.encode("Content-Encoding: nonce\u0000"), 12);
  // registro único: payload || 0x02 (delimitador do ÚLTIMO registro, RFC 8188 §2)
  const record = concatBytes(enc.encode(payloadStr), new Uint8Array([2]));
  const aesKey = await crypto.subtle.importKey("raw", cek, "AES-GCM", false, ["encrypt"]);
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv: nonce }, aesKey, record));
  const rs = new Uint8Array([0, 0, 16, 0]); // record size 4096 (big-endian)
  const header = concatBytes(salt, rs, new Uint8Array([asPublic.length]), asPublic);
  return concatBytes(header, ct);
}

/* RFC 8292 — VAPID JWT (ES256). aud = origem do push service do endpoint;
   exp = +12h; sub = mailto do responsável. Chaves: P-256 raw em base64url
   (pública = 65 bytes não comprimida; privada = escalar d de 32 bytes). */
async function vapidJwt(env, audience) {
  const pubBytes = b64uToBytes(env.VAPID_PUBLIC_KEY);
  const privBytes = b64uToBytes(env.VAPID_PRIVATE_KEY);
  if (pubBytes.length !== 65) throw new Error("VAPID_PUBLIC_KEY inválida (esperado 65 bytes)");
  if (privBytes.length !== 32) throw new Error("VAPID_PRIVATE_KEY inválida (esperado 32 bytes)");
  const jwk = {
    kty: "EC", crv: "P-256",
    x: bytesToB64u(pubBytes.slice(1, 33)),
    y: bytesToB64u(pubBytes.slice(33, 65)),
    d: bytesToB64u(privBytes),
  };
  const key = await crypto.subtle.importKey("jwk", jwk, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
  const enc = new TextEncoder();
  const header = bytesToB64u(enc.encode(JSON.stringify({ typ: "JWT", alg: "ES256" })));
  const claims = bytesToB64u(enc.encode(JSON.stringify({
    aud: audience,
    exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: env.VAPID_SUBJECT || "mailto:contato@agendaidseven.com.br",
  })));
  const signingInput = header + "." + claims;
  const sig = new Uint8Array(await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, enc.encode(signingInput)));
  return signingInput + "." + bytesToB64u(sig);
}

/* RFC 8030 — POST real ao push service de UMA subscription.
   Headers: Authorization vapid, Content-Encoding aes128gcm, TTL, Urgency, Topic.
   404/410 = subscription morta (gone) → chamador remove do Firestore. */
async function sendWebPushTo(env, sub, payloadObj, opts) {
  const endpoint = sub && sub.endpoint;
  const keys = sub && sub.keys;
  if (!endpoint || !keys || !keys.p256dh || !keys.auth) return { ok: false, error: "subscription inválida" };
  const audience = new URL(endpoint).origin;
  const jwt = await vapidJwt(env, audience);
  const body = await encryptWebPushPayload(JSON.stringify(payloadObj), keys.p256dh, keys.auth);
  const headers = {
    "Authorization": "vapid t=" + jwt + ", k=" + env.VAPID_PUBLIC_KEY,
    "Content-Encoding": "aes128gcm",
    "Content-Type": "application/octet-stream",
    "Content-Length": String(body.length),
    "TTL": String((opts && opts.ttl) || 86400),
    "Urgency": (opts && opts.urgency) || "high",
  };
  if (opts && opts.topic) headers["Topic"] = String(opts.topic).replace(/[^A-Za-z0-9_\-=]/g, "").slice(0, 32);
  const res = await fetch(endpoint, { method: "POST", headers, body });
  if (res.status === 404 || res.status === 410) return { ok: false, gone: true, status: res.status };
  if (res.status >= 200 && res.status < 300) return { ok: true, status: res.status };
  let detail = "";
  try { detail = (await res.text()).slice(0, 160); } catch (_) {}
  return { ok: false, status: res.status, error: detail };
}

/* V64.43 — envio REAL a uma lista de subscriptions; gated por VAPID_*.
   Retorna {sent, total, gone[], results[]}; gone[] = endpoints 404/410 a remover. */
async function broadcastWebPush(env, subs, payload, opts) {
  if (!env.VAPID_PRIVATE_KEY || !env.VAPID_PUBLIC_KEY || !env.VAPID_SUBJECT) {
    return { sent: 0, total: (subs && subs.length) || 0, gone: [], skipped: "VAPID_NOT_CONFIGURED" };
  }
  const results = [];
  const gone = [];
  for (const sub of subs) {
    try {
      const r = await sendWebPushTo(env, sub, payload, opts);
      results.push(r);
      if (r.gone && sub.endpoint) gone.push(sub.endpoint);
    } catch (e) {
      results.push({ ok: false, error: e && e.message });
    }
  }
  return { sent: results.filter((r) => r.ok).length, total: subs.length, gone, results };
}

/* V64.43 — remove subscriptions mortas (404/410) do array tasks/{id}.clientPushSubs.
   Reescreve o campo filtrado via updateMask (best-effort; falha não bloqueia o fluxo). */
async function pruneClientPushSubs(env, task, goneEndpoints) {
  const keep = (Array.isArray(task.clientPushSubs) ? task.clientPushSubs : [])
    .filter((s) => s && goneEndpoints.indexOf(s.endpoint) < 0);
  const accessToken = await getAccessToken(env, DATASTORE_SCOPE);
  const values = keep.map((s) => ({ mapValue: { fields: {
    endpoint: { stringValue: s.endpoint || "" },
    keys: { mapValue: { fields: {
      p256dh: { stringValue: (s.keys && s.keys.p256dh) || "" },
      auth: { stringValue: (s.keys && s.keys.auth) || "" },
    } } },
    at: { integerValue: String(s.at || 0) },
  } } }));
  const docName = `projects/${env.FCM_PROJECT_ID}/databases/(default)/documents/tasks/${task.id}`;
  const body = { writes: [{
    update: { name: docName, fields: { clientPushSubs: { arrayValue: { values } } } },
    updateMask: { fieldPaths: ["clientPushSubs"] },
  }] };
  await fetch(`${FIRESTORE_BASE}/projects/${env.FCM_PROJECT_ID}/databases/(default)/documents:commit`, {
    method: "POST",
    headers: { "Authorization": "Bearer " + accessToken, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  console.log(`[PUSH-PRUNE] task=${task.id} removidas=${goneEndpoints.length} restantes=${keep.length}`);
}

/* ═══════════════ V64.43 — NOTIFICATION ENGINE central ═══════════════
   notifyWorkflowEvent(env, task, eventType, payload?)
   Tabela única: destinatário, fase, title/body. Canal principal do CLIENTE =
   Web Push real; fallback = WhatsApp premium (card enviado pelo fluxo existente,
   operado pela equipe — o engine sinaliza `fallback:'whatsapp_premium'`).
   Eventos de EQUIPE seguem os fluxos FCM já existentes (/notify-assignee,
   /notify-designer) — o engine registra e loga sem duplicar envio.
   Dedup: 1 disparo por (taskId|evento|item) por 60s via Cache API. */
const NOTIFY_EVENTS = {
  // V64.49 — copy EXATA aprovada para o cliente (título/mensagem por evento).
  themes_sent_to_client:        { to: "client", phase: "themes",     title: "Cronograma disponível para análise", body: "Os temas do seu cronograma estão prontos para revisão." },
  theme_adjusted_by_team:       { to: "client", phase: "themes",     title: "Tema corrigido",                     body: "O tema ajustado foi reenviado. Toque para revisar." },
  themes_approved_by_client:    { to: "client", phase: "themes",     title: "Temas aprovados",                    body: "A etapa de temas foi aprovada com sucesso." },
  designer_assigned:            { to: "team",   phase: "production", title: "Designer atribuído",                 body: "O cronograma entrou na fila do designer." },
  designer_started:             { to: "team",   phase: "production", title: "Designer em produção",               body: "O designer iniciou a produção do cronograma." },
  designer_delivered:           { to: "team",   phase: "production", title: "Designer entregou",                  body: "Revise, adicione legendas e posts e envie ao cliente." },
  final_content_sent_to_client: { to: "client", phase: "final",      title: "Legendas e posts disponíveis",       body: "As legendas e os posts estão prontos para sua análise." },
  final_adjusted_by_team:       { to: "client", phase: "final",      title: "Ajuste final realizado",             body: "As correções finais foram enviadas. Toque para revisar." },
  final_approved_by_client:     { to: "client", phase: "final",      title: "Cronograma finalizado",              body: "Seu cronograma foi aprovado com sucesso." },
};

async function notifyWorkflowEvent(env, task, eventType, payload) {
  const ev = NOTIFY_EVENTS[eventType];
  if (!ev) return { ok: false, error: "evento desconhecido: " + eventType };
  const token = (task && (task.clientReviewToken || task.shareToken)) || (payload && payload.token) || "";
  const openUrl = token ? ("/cliente/cronograma/" + token) : "/";
  // anti-duplicidade: 1 disparo por (task|evento|item) numa janela de 60s
  const dedupKey = `${(task && task.id) || ""}|${eventType}|${(payload && payload.contentIndex != null) ? payload.contentIndex : ""}`;
  const dedupUrl = "https://notify-dedup.local/" + encodeURIComponent(dedupKey);
  try {
    const hit = await caches.default.match(new Request(dedupUrl));
    if (hit) {
      console.log(`[NOTIFY] dedup task=${task && task.id} event=${eventType}`);
      return { ok: true, deduped: true, eventType };
    }
  } catch (_) { /* Cache API indisponível → segue sem dedup */ }

  let result = { channel: "none", sent: 0 };
  if (ev.to === "client") {
    const subs = Array.isArray(task && task.clientPushSubs) ? task.clientPushSubs : [];
    if (subs.length && env.VAPID_PRIVATE_KEY && env.VAPID_PUBLIC_KEY && env.VAPID_SUBJECT) {
      // V64.49 — PRECISÃO: o payload carrega eventType/taskId/phase além de título/corpo/URL.
      const out = await broadcastWebPush(env, subs,
        { title: ev.title, body: ev.body, openUrl, tag: dedupKey,
          icon: "/og/idseven-logo.png", badge: "/og/idseven-badge.png",
          eventType, taskId: (task && task.id) || "", phase: ev.phase },
        { topic: eventType, urgency: "high", ttl: 86400 });
      result = { channel: "webpush", sent: out.sent, total: out.total };
      // V64.50 — VERDADE no log: status REAL do POST por endpoint (mascarado). Falha de envio
      // com subscription presente é ERRO (reason=send_failed), NUNCA confundida com
      // 'sem_subscription'; o fallback WhatsApp é informado como fallback, não como envio.
      result.results = (out.results || []).map((r, i) => ({
        endpoint: maskEndpoint(subs[i] && subs[i].endpoint), ok: !!r.ok,
        status: r.status || 0, gone: !!r.gone, error: r.error || null,
      }));
      if (out.gone && out.gone.length) {
        try { await pruneClientPushSubs(env, task, out.gone); } catch (_) { /* best-effort */ }
        result.pruned = out.gone.length;
      }
      if (!out.sent) { result.fallback = "whatsapp_premium"; result.reason = "send_failed"; result.error = "push_send_failed"; }
    } else {
      result = { channel: "none", sent: 0, fallback: "whatsapp_premium",
                 reason: subs.length ? "VAPID_NOT_CONFIGURED" : "sem_subscription" };
    }
  } else {
    // equipe: FCM já coberto por /notify-assignee e /notify-designer (fluxos existentes).
    result = { channel: "fcm_existing_flows", sent: 0 };
  }
  try {
    await caches.default.put(new Request(dedupUrl),
      new Response("1", { status: 200, headers: { "Cache-Control": "public, max-age=60" } }));
  } catch (_) { /* sem dedup persistido */ }
  const subsFound = (ev.to === "client") ? ((Array.isArray(task && task.clientPushSubs) ? task.clientPushSubs : []).length) : null;
  console.log(`[NOTIFY] task=${task && task.id} event=${eventType} phase=${ev.phase} to=${ev.to} openUrl=${openUrl} dedupKey=${dedupKey} subsFound=${subsFound} result=${JSON.stringify(result)}`);
  return Object.assign({ ok: true, eventType, phase: ev.phase, to: ev.to, openUrl }, result);
}

/* V64.16 — ESTADO JSON p/ TEMPO REAL. O portal faz polling leve e atualiza tema/legenda/Feed/
   Story/badge sem recarregar, no MESMO link. Sem cache (no-store). */
async function handleClientCronogramaState(token, env) {
  try {
    let accessToken;
    try { accessToken = await getAccessToken(env, FCM_SCOPE + " " + DATASTORE_SCOPE); }
    catch (e) { return json({ ok: false, error: "auth" }, 200, env); }
    const task = await queryTaskByToken(env, accessToken, token);
    if (!task) return json({ ok: false, error: "not_found" }, 200, env);
    const items = Array.isArray(task.cronWeeks) ? task.cronWeeks : (Array.isArray(task.cronContents) ? task.cronContents : []);
    const ci = (task.clientItems && typeof task.clientItems === "object") ? task.clientItems : {};
    const firstUrl = (v) => { if (!v) return ""; if (typeof v === "string") return v; if (Array.isArray(v)) { for (const z of v) { if (z && typeof z === "string") return z; if (z && z.url) return z.url; } return ""; } return v.url || ""; };
    const out = items.map((raw, i) => {
      const c = (raw && typeof raw === "object") ? raw : {};
      const ov = ci["i" + i] || {};
      const tema = (typeof ov.theme === "string" && ov.theme) ? ov.theme : (c.t || c.tema || ("Conteúdo " + (i + 1)));
      const legRaw = (typeof ov.legenda === "string") ? ov.legenda : (typeof c.legenda === "string" ? c.legenda : (typeof c.caption === "string" ? c.caption : (typeof c.lg === "string" ? c.lg : (typeof c.l === "string" ? c.l : ""))));
      return { i, cs: ov.cs || c.cs || "", tema, legenda: (legRaw || "").toString(),
        feed: firstUrl(c.feed) || (c.feedImageUrl || ""), story: firstUrl(c.story || c.stories) || (c.storyImageUrl || "") };
    });
    // V64.47 — pendência POR FASE + override "todos aprovados": item de outra fase não conta;
    // se TODOS os conteúdos da fase atual estão aprovados, NÃO há pendência mesmo que o
    // clientReview.status global ainda esteja 'revisao' (estado herdado do ciclo de ajuste).
    const ph = clientPhase(task);
    const itemPending = Object.keys(ci).some((k) => { const it = ci[k]; const cs = it && it.cs; return (cs === "em_revisao" || cs === "editado") && it.phase === ph; });
    let allApproved = out.length > 0;
    for (let i = 0; i < out.length; i++) { const it = ci["i" + i]; if (!(it && it.cs === "aprovado" && it.phase === ph)) { allApproved = false; break; } }
    const pendingRevision = !allApproved && (itemPending || (task.clientReview && task.clientReview.status === "revisao"));
    const finalDone = task.finalApprovalCompleted === true || task.clientFlowStatus === "concluido";
    return json({ ok: true, phase: ph, pendingRevision, phaseApproved: allApproved, finalDone, updatedAt: task.updatedAt || 0, items: out }, 200, env);
  } catch (e) {
    return json({ ok: false, error: "err" }, 200, env);
  }
}

/* Persistência ADITIVA e granular do feedback do cliente (V64.7).
   NÃO reescreve cronWeeks (evita clobber de edição concorrente do Desktop) e NÃO
   toca cronStatus/clientReview/history. Grava em 3 campos novos (merge por updateMask):
     - clientLastAction : map  {type, at, note, contentIndex} (compat com leitura existente)
     - clientActions.a<at> : map  log granular {type, at, contentIndex, field, newValue, note}
     - clientItems.i<idx>  : map  estado do item p/ o cliente {cs, theme, legenda, note, at}
   A Desktop lê clientItems/clientActions para mostrar exatamente o que o cliente mexeu. */
async function writeClientGranular(env, accessToken, task, e) {
  const taskId = task.id;
  const at = e.at;
  const aid = "a" + at;                  // chave de ação (começa com letra → field path válido)
  const perItem = ["approveItem", "reviseItem", "editTheme", "editLegenda", "noteItem"].indexOf(e.type) >= 0 && e.contentIndex != null;

  // log granular (clientActions.<aid>)
  const actFields = { type: { stringValue: e.type }, at: { integerValue: String(at) } };
  if (e.contentIndex != null) actFields.contentIndex = { integerValue: String(e.contentIndex) };
  if (e.note) actFields.note = { stringValue: e.note };
  if (e.type === "editTheme") { actFields.field = { stringValue: "tema" }; actFields.newValue = { stringValue: e.value }; }
  if (e.type === "editLegenda") { actFields.field = { stringValue: "legenda" }; actFields.newValue = { stringValue: e.value }; }

  // clientLastAction (compat de leitura)
  const lastActionFields = {
    type: { stringValue: e.type }, at: { integerValue: String(at) }, note: { stringValue: e.note || "" },
  };
  if (e.contentIndex != null) lastActionFields.contentIndex = { integerValue: String(e.contentIndex) };

  const fields = {
    clientLastAction: { mapValue: { fields: lastActionFields } },
    clientActions: { mapValue: { fields: { [aid]: { mapValue: { fields: actFields } } } } },
    updatedAt: { integerValue: String(at) },                 // sinaliza mudança p/ quem observa
  };
  const mask = ["clientLastAction", "clientActions." + aid, "updatedAt"];

  // estado POR item (clientItems.i<idx>)
  if (perItem) {
    const key = "i" + e.contentIndex;
    const itemFields = { at: { integerValue: String(at) } };
    // task-flow-fix (BUG #6): marca a FASE em que o item foi avaliado (themes/production/final),
    // para que aprovações/ajustes de uma fase NÃO contaminem a decisão de outra fase.
    itemFields.phase = { stringValue: clientPhase(task) };
    if (e.type === "approveItem") itemFields.cs = { stringValue: "aprovado" };
    else if (e.type === "reviseItem") { itemFields.cs = { stringValue: "em_revisao" }; if (e.note) itemFields.note = { stringValue: e.note }; }
    else if (e.type === "editTheme") { itemFields.cs = { stringValue: "editado" }; itemFields.theme = { stringValue: e.value }; }
    else if (e.type === "editLegenda") { itemFields.cs = { stringValue: "editado" }; itemFields.legenda = { stringValue: e.value }; }
    else if (e.type === "noteItem") { if (e.note) itemFields.note = { stringValue: e.note }; }
    fields.clientItems = { mapValue: { fields: { [key]: { mapValue: { fields: itemFields } } } } };
    mask.push("clientItems." + key);
  }

  /* ───── V64.9 (fluxo lógico): além de cronStatus/clientReview, MOVE a coluna do
     kanban (campo `status`) conforme a fase, e registra `workflowStage` (aditivo):
       • aprovação INICIAL dos temas → status='andamento' (Em andamento), stage='producao'
       • aprovação FINAL (reenvio) → status='concluido', stage='concluido'
       • revisão / edição → status='revisao', stage='revisao'
     Fase detectada pelo cronStatus atual: 'ready_for_final_client_review' (reenvio) = final. ───── */
  // V64.13 — Fase de entrada (explícita via clientApprovalPhase OU derivada).
  // SÓ 'final' encerra. 'themes'/'production' continuam o fluxo com clientFlowStatus='aprovado'.
  const phaseIn = clientPhase(task);
  const isFinalPhase = phaseIn === "final";
  // V64.11 — EIXOS SEPARADOS: além de `status`/`workflowStage` (compat), grava o eixo
  // DO CLIENTE (`clientFlowStatus`/`clientWorkflowStage`). A tarefa NÃO sai do fluxo do
  // cliente quando vai ao designer; só sai de cena na aprovação FINAL (clientFlowStatus=concluido).
  //   client: 'aprovado' (temas aprovados) | 'revisao' (pediu ajuste) | 'concluido' (aprovação final)
  const approveG = isFinalPhase
    ? { cs: "aprovado_cliente", rev: "aprovado", htype: "cliente_aprovou_final", label: "Cliente aprovou a entrega final", col: "concluido", stage: "concluido", client: "concluido" }
    : { cs: "aprovado_cliente", rev: "aprovado", htype: "cliente_aprovou",       label: "Cliente aprovou os temas/cronograma", col: "andamento", stage: "producao", client: "aprovado" };
  const STAT = {
    approve:      approveG,
    approveAll:   approveG,
    revision:     { cs: "em_revisao_cliente", rev: "revisao", htype: "cliente_pediu_revisao", label: "Cliente pediu revisão geral",         col: "revisao", stage: "revisao", client: "revisao" },
    reviseItem:   { cs: "em_revisao_cliente", rev: "revisao", htype: "cliente_pediu_revisao", label: "Cliente pediu ajuste em um conteúdo", col: "revisao", stage: "revisao", client: "revisao" },
    edit_request: { cs: "editado_cliente",    rev: "editado", htype: "cliente_editou",        label: "Cliente solicitou edição",            col: "revisao", stage: "revisao", client: "revisao" },
    editTheme:    { cs: "editado_cliente",    rev: "editado", htype: "cliente_editou",        label: "Cliente editou o tema de um conteúdo",    col: "revisao", stage: "revisao", client: "revisao" },
    editLegenda:  { cs: "editado_cliente",    rev: "editado", htype: "cliente_editou",        label: "Cliente editou a legenda de um conteúdo", col: "revisao", stage: "revisao", client: "revisao" },
    noteItem:     { cs: null, rev: null, htype: "cliente_comentou", label: "Cliente deixou uma observação", col: null, stage: null, client: null },
    comment:      { cs: null, rev: null, htype: "cliente_comentou", label: "Cliente comentou no cronograma", col: null, stage: null, client: null },
  };
  let g = STAT[e.type] || { cs: null, rev: null, htype: "cliente_acao", label: "Ação do cliente", col: null, stage: null, client: null };

  // V64.16 / task-flow-fix — GATE de aprovação PARCIAL, agora POR FASE: se QUALQUER conteúdo
  // DA FASE ATUAL tem ajuste/edição pendente, 'approve'/'approveAll' NÃO conclui nem libera —
  // vira feedback (revisão). Revisões de fases ANTERIORES (ex.: ajuste de tema já resolvido no
  // reenvio) NÃO contaminam a fase final (filtra por phase === phaseIn).
  const _ci0 = (task.clientItems && typeof task.clientItems === "object") ? task.clientItems : {};
  const _pendingRev = Object.keys(_ci0).some((k) => {
    const it = _ci0[k]; if (!it) return false;
    const cs = it.cs; const ph = it.phase;
    return (cs === "em_revisao" || cs === "editado") && (ph === phaseIn);
  });
  if ((e.type === "approve" || e.type === "approveAll") && _pendingRev) {
    g = { cs: "em_revisao_cliente", rev: "revisao", htype: "cliente_enviou_feedback",
          label: "Cliente enviou feedback (há ajustes pendentes)", col: "revisao", stage: "revisao", client: "revisao" };
  }

  // task-flow-fix (BUG #6): approveItem aprova SOMENTE o item clicado e NUNCA conclui nem avança
  // de fase. A conclusão/avanço só ocorre via ação EXPLÍCITA do cliente (approveAll). Antes, a
  // contagem global de clientItems.cs==='aprovado' (sem separar fase) fazia o 1º item da fase
  // final fechar tudo, porque as aprovações de TEMAS persistiam em clientItems.
  if (e.type === "approveItem") {
    g = { cs: null, rev: null, htype: "cliente_aprovou_item", label: "Cliente aprovou um conteúdo", col: null, stage: null, client: null };
    // V64.49 — REGRA EXPLÍCITA (reprovação 1.0.134): aprovar o ÚLTIMO item NUNCA fecha a
    // fase automaticamente. Quem fecha é SEMPRE o botão final do portal ("Aprovar temas" →
    // approveAll). O rodapé dinâmico (syncFooter) garante o CTA correto quando tudo está
    // aprovado, e o approveAll permanece phase-aware (V64.47) — o doc não trava mais em
    // 'revisao' herdado porque o gate de pendência conta SÓ itens da fase atual.
  }

  if (g.cs) {
    fields.cronStatus = { stringValue: g.cs };
    fields.clientReview = { mapValue: { fields: {
      status: { stringValue: g.rev },
      note: { stringValue: e.note || "" },
      at: { integerValue: String(at) },
      byName: { stringValue: "Cliente" },
    } } };
    fields.clientReviewAt = { integerValue: String(at) };
    mask.push("cronStatus", "clientReview", "clientReviewAt");
  }
  const statusFrom = (task.status || "afazer");
  if (g.col) { fields.status = { stringValue: g.col }; mask.push("status"); }
  if (g.stage) { fields.workflowStage = { stringValue: g.stage }; mask.push("workflowStage"); }
  // V64.11 — eixo do CLIENTE (independente do designer; só conclui na aprovação final).
  const clientFrom = (task.clientFlowStatus || "");
  if (g.client) {
    fields.clientFlowStatus = { stringValue: g.client };
    fields.clientWorkflowStage = { stringValue: g.client };
    mask.push("clientFlowStatus", "clientWorkflowStage");
  }
  // V64.12 — APROVAÇÃO FINAL: registra encerramento do eixo do cliente + operacional.
  // NÃO apaga socialFlowStatus/designerFlowStatus (updateMask só toca os campos abaixo).
  if (g.client === "concluido") {
    fields.clientFinalApprovedAt = { integerValue: String(at) };
    fields.clientFinalApprovedBy = { stringValue: "Cliente" };
    fields.finalApprovalCompleted = { booleanValue: true };
    fields.operationalStatus = { stringValue: "concluido" };
    fields.clientClosedMessageShown = { booleanValue: true };
    mask.push("clientFinalApprovedAt", "clientFinalApprovedBy", "finalApprovalCompleted", "operationalStatus", "clientClosedMessageShown");
  }

  // V64.42 — LIMPEZA POR TRANSIÇÃO DE FASE: ao approveAll com SUCESSO de uma fase (themes ou
  // final), zera `cs` dos itens DAQUELA fase. O chip vermelho ("em_revisao"/"editado") de itens
  // já resolvidos não polui mais a tela das fases seguintes. Mantém `phase` (auditoria).
  if (g.client === "aprovado" || g.client === "concluido") {
    const phaseCleanup = phaseIn;
    if (!fields.clientItems) fields.clientItems = { mapValue: { fields: {} } };
    for (const k of Object.keys(_ci0)) {
      const it = _ci0[k]; if (!it || it.phase !== phaseCleanup) continue;
      const slot = fields.clientItems.mapValue.fields[k] || { mapValue: { fields: {} } };
      slot.mapValue.fields.cs = { nullValue: null };
      fields.clientItems.mapValue.fields[k] = slot;
      mask.push("clientItems." + k + ".cs");
    }
  }

  // entrada de histórico (arrayUnion via appendMissingElements — REST :commit)
  const histFields = {
    type: { stringValue: g.htype },
    label: { stringValue: g.label },
    at: { integerValue: String(at) },
    by: { stringValue: "Cliente" },
    channel: { stringValue: "client_public" },
    client: { stringValue: (task.client || "") },
    note: { stringValue: e.note || "" },
  };
  if (e.contentIndex != null) histFields.contentIndex = { integerValue: String(e.contentIndex) };
  if (g.col && g.col !== statusFrom) { histFields.statusFrom = { stringValue: statusFrom }; histFields.statusTo = { stringValue: g.col }; }
  if (g.client && g.client !== clientFrom) { histFields.clientFrom = { stringValue: clientFrom }; histFields.clientTo = { stringValue: g.client }; }
  const histValue = { mapValue: { fields: histFields } };

  const docName = `projects/${env.FCM_PROJECT_ID}/databases/(default)/documents/tasks/${taskId}`;
  const body = {
    writes: [{
      update: { name: docName, fields },
      updateMask: { fieldPaths: mask },
      updateTransforms: [{ fieldPath: "history", appendMissingElements: { values: [histValue] } }],
    }],
  };
  const url = `${FIRESTORE_BASE}/projects/${env.FCM_PROJECT_ID}/databases/(default)/documents:commit`;
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Authorization": "Bearer " + accessToken, "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!res.ok) console.warn("[CLIENT-ACTION] commit falhou:", res.status, (await res.text()).slice(0, 240));
    else console.log(`[CLIENT-ACTION] commit ok task=${taskId} type=${e.type} cronStatus=${g.cs || "(inalterado)"}`);
  } catch (err) {
    console.warn("[CLIENT-ACTION] erro ao gravar feedback granular:", err && err.message);
  }
  return g;   // {cs, rev, htype, label, col, stage} — handler usa p/ saber se concluiu (col==='concluido')
}

/* Query Firestore pela task que corresponde ao token público do cliente.
   O token pode estar em DOIS campos, conforme a origem do link:
     - clientReviewToken  → Desktop (genReviewToken → ensureReviewToken)
     - shareToken         → Web/PWA (genShareToken)
   Tenta clientReviewToken primeiro (origem dos links /cliente/cronograma/<token>),
   depois shareToken como fallback. Equality simples — não exige índice composto. */
async function queryTaskByToken(env, accessToken, token) {
  for (const field of ["clientReviewToken", "shareToken"]) {
    const task = await queryTaskByField(env, accessToken, field, token);
    if (task) { console.log(`[CLIENT-VIEW] task achada por ${field}`); return task; }
  }
  return null;
}

async function queryTaskByField(env, accessToken, field, value) {
  const url = `${FIRESTORE_BASE}/projects/${env.FCM_PROJECT_ID}/databases/(default)/documents:runQuery`;
  const q = {
    structuredQuery: {
      from: [{ collectionId: "tasks" }],
      where: { fieldFilter: { field: { fieldPath: field }, op: "EQUAL", value: { stringValue: value } } },
      limit: 1,
    },
  };
  const res = await fetch(url, {
    method: "POST",
    headers: { "Authorization": "Bearer " + accessToken, "Content-Type": "application/json" },
    body: JSON.stringify(q),
  });
  if (!res.ok) {
    // Distingue FALHA de query (auth/permissão/Firestore) de "não encontrado".
    // Lança para o handler cair no catch (página "Algo deu errado", 500) em vez de
    // mascarar como 404 — assim um problema de infra não vira "link inválido".
    const body = (await res.text()).slice(0, 200);
    console.error(`[CLIENT-VIEW] runQuery(${field}) falhou:`, res.status, body);
    throw new Error(`firestore runQuery ${field} ${res.status}: ${body}`);
  }
  const rows = await res.json();
  for (const row of rows) {
    if (!row.document) continue;
    const id = row.document.name.split("/").pop();
    return Object.assign({ id }, decodeFields(row.document.fields));
  }
  return null;
}

/* Grava tasks/{id}.clientLastAction (CAMPO NOVO ADITIVO) — não toca cronWeeks/cs/lg/lgState. */
async function writeClientLastAction(env, accessToken, taskId, action) {
  const url = `${FIRESTORE_BASE}/projects/${env.FCM_PROJECT_ID}/databases/(default)/documents/tasks/${taskId}?updateMask.fieldPaths=clientLastAction`;
  try {
    await fetch(url, {
      method: "PATCH",
      headers: { "Authorization": "Bearer " + accessToken, "Content-Type": "application/json" },
      body: JSON.stringify({
        fields: {
          clientLastAction: {
            mapValue: {
              fields: {
                type: { stringValue: action.type },
                at: { integerValue: String(action.at) },
                note: { stringValue: action.note || "" },
              },
            },
          },
        },
      }),
    });
  } catch (e) {
    console.warn("[CLIENT-ACTION] falha ao gravar clientLastAction:", e && e.message);
  }
}

function htmlResponse(html, status) {
  return new Response(html, {
    status: status || 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-store",
      "X-Content-Type-Options": "nosniff",
      "Referrer-Policy": "no-referrer",
    },
  });
}

function escapeHtml(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

function frequencyLabel(t) {
  const f = (t.freq || t.frequencia || t.cronFrequency || "").toString().toLowerCase();
  const map = { semanal: "Semanal", quinzenal: "Quinzenal", mensal: "Mensal", unico: "Único" };
  return map[f] || (f ? f.charAt(0).toUpperCase() + f.slice(1) : "Cronograma");
}

// V64.13 — Fase REAL da aprovação do cliente.
// 'themes' = primeiro envio (só temas) · 'production' = legendas/posts em validação
// 'final' = aprovação final (reenvio após produção). Explícito > derivado.
function clientPhase(task) {
  const explicit = (task.clientApprovalPhase || "").toString();
  if (explicit === "themes" || explicit === "production" || explicit === "final") return explicit;
  if (task.finalApprovalCompleted === true) return "final";
  if (task.cronStatus === "ready_for_final_client_review"
      || task.workflowStage === "entrega" || task.workflowStage === "revisao_final") return "final";
  // Deriva pela completude do conteúdo: todas com legenda E todas com Feed -> produção/final-prox.
  const arr = Array.isArray(task.cronWeeks) ? task.cronWeeks
    : (Array.isArray(task.cronContents) ? task.cronContents : []);
  const total = arr.length || 0;
  if (total > 0) {
    const withLegend = arr.filter((c) => c && c.legenda && String(c.legenda).trim()).length;
    const withFeed = arr.filter((c) => c && c.feedImageUrl).length;
    if (withLegend === total && withFeed === total) return "production";
  }
  return "themes";
}
function phaseCopy(phase) {
  if (phase === "final") return {
    kicker: "Aprovação final do cronograma",
    title: "Aprovação final do cronograma",
    sub: "Confira legendas, Feed e Story. Ao aprovar aqui, o processo é encerrado.",
    cta: "Aprovar versão final",
  };
  if (phase === "production") return {
    kicker: "Aprovação de legendas e artes",
    title: "Aprovação de legendas e artes",
    sub: "Confira as legendas e as artes. Ainda haverá uma etapa final.",
    cta: "Aprovar legendas e artes",
  };
  return {
    kicker: "Aprovação de temas",
    title: "Aprovação de temas",
    sub: "Você está aprovando apenas os temas. A equipe seguirá com a produção (designer + legendas + posts).",
    cta: "Aprovar temas",
  };
}
/* V64.14 — Fase JÁ aprovada pelo cliente (para mostrar confirmação intermediária no reabrir).
   Retorna 'themes' | 'production' | null. NUNCA esconde uma aprovação ainda necessária:
   - themes: aprovou e a produção ainda não está pronta (fase derivada continua 'themes').
   - production: só quando a fase está EXPLICITAMENTE marcada 'production' E já aprovada.
   - final é tratado pela tela de sucesso (não entra aqui). */
function clientAckedPhase(task) {
  const cr = (task.clientReview && task.clientReview.status) || "";
  const approved = cr === "aprovado" || task.cronStatus === "aprovado_cliente" || task.clientFlowStatus === "aprovado";
  if (!approved) return null;
  const ph = clientPhase(task);
  if (ph === "final") return null;
  if (ph === "themes") return "themes";
  if (ph === "production" && (task.clientApprovalPhase || "") === "production") return "production";
  return null;
}
/* V64.14 — Página INTERMEDIÁRIA server-rendered (reabrir após aprovar temas/produção).
   Mantém o MESMO link, sem botões de ação abertos, com linguagem da fase seguinte. */
function renderClientPhaseAckHtml(task, token, phase, origin) {
  const cliente = escapeHtml(task.client || "Cliente");
  const titulo = escapeHtml(task.title || "Cronograma");
  const isThemes = phase === "themes";
  const h2 = isThemes ? "Temas aprovados!" : "Legendas e artes aprovadas!";
  const msg = isThemes
    ? "A equipe seguirá para a etapa de produção (designer, legendas e posts). Em breve você receberá a versão final neste mesmo link para a aprovação final."
    : "A equipe enviará a versão final completa para a sua aprovação. Em breve você receberá o aviso neste mesmo link.";
  const next = isThemes ? "Aguardando produção · legendas e artes" : "Aguardando aprovação final";
  return '<!doctype html>\n<html lang="pt-BR"><head>\n' +
'<meta charset="utf-8"/>\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"/>\n' +
ogClientMeta(origin, "Aprovar cronograma — " + (task.client || "Cliente"), "Acompanhe a aprovação do seu cronograma. Link seguro · Agenda ID Seven.", "/cliente/cronograma/" + token) +
'<title>' + cliente + ' · ' + titulo + ' · Visão do Cliente</title>\n<meta name="theme-color" content="#070810"/>\n' +
'<meta name="robots" content="noindex,nofollow"/>\n' +
'<style>' + CV_CSS + '</style></head><body>\n' +
'<div class="wrap"><div class="topbar"><div class="brand">' + CV_LOGO + '<div class="bn">Agenda ID Seven<small>Visão do Cliente</small></div></div>' +
  '<div class="secure">' + ICN.shield + '<span class="lbl">Link seguro</span></div></div>' +
  '<div class="midwrap"><div class="midcard"><div class="mid-badge">' + ICN.check + '</div>' +
    '<h2>' + h2 + '</h2><p>' + msg + '</p>' +
    '<div class="phase-banner phase-' + (isThemes ? "production" : "final") + '" style="justify-content:center;margin-top:16px"><span class="phase-dot"></span><b>' + next + '</b></div>' +
    '<div class="mid-foot">Você pode fechar esta página — vamos te avisar. 💜</div></div></div>' +
'</div></body></html>';
}
function statusLabel(t) {
  const cls = (t.cronStatus || "").toString();
  const map = {
    sent_to_designer: "Enviado ao designer",
    in_design: "Em produção",
    ready_for_client: "Pronto para o cliente",
    in_client_review: "Em análise do cliente",
    client_revision: "Cliente pediu revisão",
    client_approved: "Aprovado pelo cliente",
    delivered: "Entregue",
  };
  if (map[cls]) return map[cls];
  const s = (t.status || "").toString();
  const m2 = { afazer: "A fazer", andamento: "Em andamento", revisao: "Em revisão", concluido: "Concluído" };
  return m2[s] || "Em produção";
}

function csLabel(cs) {
  return {
    enviado: "Enviado ao cliente",
    em_analise: "Em análise",
    em_revisao: "Revisão pedida",
    aprovado: "Aprovado",
    concluido: "Entregue",
  }[cs] || "";
}

function lgStateLabel(s) {
  return {
    pendente: "Pendente",
    escrita: "Em escrita",
    enviada: "Enviada",
    em_analise: "Em análise",
    em_revisao: "Revisão pedida",
    aprovada: "Aprovada",
  }[s] || "Pendente";
}

function feedCount(c) {
  if (Array.isArray(c.feed)) return c.feed.length;
  if (c.feed && typeof c.feed === "object" && c.feed.url) return 1;
  return 0;
}
function storyCount(c) {
  if (Array.isArray(c.stories)) return c.stories.length;
  if (c.story && typeof c.story === "object" && c.story.url) return 1;
  return 0;
}

